-- V1: the complete InterNyay schema.
--
-- Written to match the JPA entities exactly, because the backend runs with spring.jpa.hibernate.ddl-auto=validate:
-- on start Hibernate only checks that every entity table and column exists with a compatible type, it never alters anything.
-- Foreign keys have fixed names (fk_<table>_<what>) and are part of this file, so a fresh database needs no extra step.
--
-- Do NOT edit this file once it has been applied anywhere (Flyway checks its checksum and refuses to start if it changed).
-- Every later schema change goes into a new file: V8__what_it_does.sql, ..., see sql/README.md.
--
-- Every table is utf8mb4 / utf8mb4_unicode_ci explicitly, so joins and foreign keys never hit Error 1267 (mixed collations).

-- ---------- plans (users.plan_code points at plans.code) ----------
CREATE TABLE plans (
  id                    BIGINT       NOT NULL AUTO_INCREMENT,
  code                  VARCHAR(30)  NOT NULL,
  name                  VARCHAR(255) NOT NULL,
  tagline               VARCHAR(255),
  price_monthly         INT,
  discount_price        INT,
  price_yearly          INT,
  discount_price_yearly INT,
  coming_soon           BIT(1)       NOT NULL,
  audience              VARCHAR(20)  NOT NULL,
  most_popular          BIT(1)       NOT NULL,
  associate_limit       INT          NOT NULL,
  features              LONGTEXT,
  feature_keys          TEXT,
  sort_order            INT          NOT NULL,
  free_monthly          BIT(1)       NOT NULL DEFAULT 0,
  free_yearly           BIT(1)       NOT NULL DEFAULT 0,
  enabled               BIT(1)       NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  CONSTRAINT uk_plans_code UNIQUE (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- users, clients ----------
CREATE TABLE users (
  id                   BIGINT       NOT NULL AUTO_INCREMENT,
  name                 VARCHAR(255) NOT NULL,
  email                VARCHAR(255) NOT NULL,
  password             VARCHAR(255) NOT NULL,
  txn_pin              VARCHAR(100),
  txn_pin_attempts     INT,
  txn_pin_locked_until DATETIME(6),
  txn_pin_changed_at   DATETIME(6),
  password_set         BIT(1)       NOT NULL,
  google_id            VARCHAR(64),
  plan_code            VARCHAR(30),
  phone                VARCHAR(255),
  bar_no               VARCHAR(255),
  specialization       VARCHAR(1000),   -- several values separated by ";"
  chamber              VARCHAR(255),
  court_preferences    VARCHAR(500),    -- ids of the preferred courts (courts.id of a court + district row), separated by ","
  profile_picture      LONGTEXT,
  upi_id               VARCHAR(255),
  qr_code_id           VARCHAR(255),
  role                 VARCHAR(255) NOT NULL,
  active               BIT(1)       NOT NULL,
  self_deactivated     BIT(1),
  advocate_code        VARCHAR(20),
  advocate_id          BIGINT,
  -- set by an admin per advocate: NULL = the plan's limit applies, -1 = unlimited
  associate_limit      INT          NULL,
  created_at           DATETIME(6),
  updated_at           DATETIME(6),
  last_login_at        DATETIME(6),
  password_changed_at  DATETIME(6),
  PRIMARY KEY (id),
  CONSTRAINT uk_users_email_role     UNIQUE (email, role),
  CONSTRAINT uk_users_advocate_code  UNIQUE (advocate_code),
  -- a plan in use cannot be removed (PlanService already blocks it)
  CONSTRAINT fk_users_plan           FOREIGN KEY (plan_code)   REFERENCES plans (code) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_users_advocate       FOREIGN KEY (advocate_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE clients (
  id               BIGINT       NOT NULL AUTO_INCREMENT,
  name             VARCHAR(255) NOT NULL,
  email            VARCHAR(255) NOT NULL,
  whatsapp_phone   VARCHAR(255),
  additional_phone VARCHAR(255),
  address          VARCHAR(255),
  profile_picture  LONGTEXT,
  type             ENUM('INDIVIDUAL','COMPANY','BANK','FINANCIAL_INSTITUTE','SOCIETY_NGO','FOREIGN_CLIENT','HOSPITAL_MEDICAL_INSTITUTE','ASSOCIATION','OTHER'),
  custom_label     ENUM('LEGAL_AID','PRO_BONO','CORPORATE_PANEL','PRIVATE'),
  user_id          BIGINT       NOT NULL,
  created_at       DATETIME(6),
  updated_at       DATETIME(6),
  PRIMARY KEY (id),
  CONSTRAINT fk_clients_user FOREIGN KEY (user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- courts, judges and the rosters built on them ----------
CREATE TABLE courts (
  id           BIGINT       NOT NULL AUTO_INCREMENT,
  court        VARCHAR(100) NOT NULL,
  district     VARCHAR(100) NOT NULL,
  building     VARCHAR(50)  NOT NULL,
  court_no     VARCHAR(50)  NOT NULL,
  high_court   BIT(1)       NOT NULL,
  mahila_court BOOLEAN      NOT NULL DEFAULT FALSE,
  PRIMARY KEY (id),
  CONSTRAINT uk_court_place UNIQUE (court, district, building, court_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE judges (
  id                   BIGINT        NOT NULL AUTO_INCREMENT,
  name                 VARCHAR(255)  NOT NULL,
  court                VARCHAR(255)  NOT NULL,
  district             VARCHAR(255)  NOT NULL,
  court_id             BIGINT,
  designation          VARCHAR(255),
  court_room_no        VARCHAR(255),
  building             VARCHAR(255),
  photo                LONGTEXT,
  vc_meeting_id        VARCHAR(255),
  court_email          VARCHAR(255),
  virtual_court_link   VARCHAR(1000),
  court_reader_name    VARCHAR(255),
  court_reader_mobile  VARCHAR(255),
  jurisdiction         TEXT,
  mahila_court         BOOLEAN       NOT NULL DEFAULT FALSE,
  created_at           DATETIME(6),
  updated_at           DATETIME(6),
  PRIMARY KEY (id),
  -- the court + district row of the judge
  CONSTRAINT fk_judges_court FOREIGN KEY (court_id) REFERENCES courts (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE judge_court_no_records (
  id            BIGINT       NOT NULL AUTO_INCREMENT,
  judge_id      BIGINT       NOT NULL,
  court_room_no VARCHAR(255) NOT NULL,
  from_date     DATE         NOT NULL,
  till_date     DATE,
  building      VARCHAR(255),
  court         VARCHAR(255),
  district      VARCHAR(255),
  PRIMARY KEY (id),
  KEY idx_court_no_record_judge (judge_id),
  -- court history goes with the judge
  CONSTRAINT fk_court_no_judge FOREIGN KEY (judge_id) REFERENCES judges (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE judges_on_leave (
  id              BIGINT       NOT NULL AUTO_INCREMENT,
  name            VARCHAR(255) NOT NULL,
  court           VARCHAR(255) NOT NULL,
  district        VARCHAR(255) NOT NULL,
  leave_from      DATE         NOT NULL,
  leave_to        DATE         NOT NULL,
  reason          VARCHAR(255),
  source          VARCHAR(20),
  hidden_by_admin BIT(1)       NOT NULL DEFAULT 0,
  created_at      DATETIME(6),
  updated_at      DATETIME(6),
  last_scraped_at DATETIME(6),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE duty_magistrate_roster (
  id            BIGINT       NOT NULL AUTO_INCREMENT,
  judge_id      BIGINT,
  court         VARCHAR(255) NOT NULL,
  district      VARCHAR(255) NOT NULL,
  court_room_no VARCHAR(255),
  judge_name    VARCHAR(255) NOT NULL,
  designation   VARCHAR(255),
  working_day   TEXT,
  holiday       TEXT,
  issued_on     DATE,
  from_date     DATE,
  till_date     DATE,
  further_order BIT(1),
  created_at    DATETIME(6),
  updated_at    DATETIME(6),
  PRIMARY KEY (id),
  -- the roster row keeps its copied text and only loses the link
  CONSTRAINT fk_duty_judge FOREIGN KEY (judge_id) REFERENCES judges (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE bail_roster_records (
  id                      BIGINT       NOT NULL AUTO_INCREMENT,
  court                   VARCHAR(255) NOT NULL,
  district                VARCHAR(255) NOT NULL,
  judicial_officers       TEXT         NOT NULL,
  judicial_officer_ids    TEXT,
  police_station_agencies TEXT,
  link_one_judge_id       BIGINT,
  link_two_judge_id       BIGINT,
  issued_on               DATE,
  from_date               DATE,
  till_date               DATE,
  further_order           BIT(1),
  created_at              DATETIME(6),
  updated_at              DATETIME(6),
  PRIMARY KEY (id),
  CONSTRAINT fk_bail_link_one FOREIGN KEY (link_one_judge_id) REFERENCES judges (id) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT fk_bail_link_two FOREIGN KEY (link_two_judge_id) REFERENCES judges (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- one row per judge on a roster entry (replaces the comma list in bail_roster_records.judicial_officer_ids)
CREATE TABLE bail_roster_judges (
  id        BIGINT NOT NULL AUTO_INCREMENT,
  roster_id BIGINT NOT NULL,
  judge_id  BIGINT NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT uk_bail_roster_judge UNIQUE (roster_id, judge_id),
  KEY idx_bail_roster_judges_judge (judge_id),
  CONSTRAINT fk_bail_judges_roster FOREIGN KEY (roster_id) REFERENCES bail_roster_records (id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_bail_judges_judge  FOREIGN KEY (judge_id)  REFERENCES judges (id)              ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- police directory, DRT and consumer jurisdiction ----------
CREATE TABLE police_districts (
  id           BIGINT       NOT NULL AUTO_INCREMENT,
  name         VARCHAR(100) NOT NULL,
  police_range VARCHAR(100),
  court        VARCHAR(100),
  default_type VARCHAR(50),
  hq           VARCHAR(500),
  dcp_post     VARCHAR(200),
  dcp_address  VARCHAR(500),
  dcp_email    VARCHAR(200),
  dcp_phone    VARCHAR(100),
  caw_post     VARCHAR(200),
  caw_address  VARCHAR(500),
  caw_email    VARCHAR(200),
  caw_phone    VARCHAR(100),
  sort_order   INT          NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE police_addl_dcps (
  id          BIGINT       NOT NULL AUTO_INCREMENT,
  district_id BIGINT       NOT NULL,
  post        VARCHAR(200),
  address     VARCHAR(500),
  email       VARCHAR(200),
  phone       VARCHAR(100),
  sort_order  INT          NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_police_addl_dcps_district FOREIGN KEY (district_id) REFERENCES police_districts (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE police_sub_divisions (
  id          BIGINT       NOT NULL AUTO_INCREMENT,
  district_id BIGINT       NOT NULL,
  acp         VARCHAR(200) NOT NULL,
  address     VARCHAR(500),
  email       VARCHAR(200),
  phone       VARCHAR(100),
  sort_order  INT          NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_police_sub_divisions_district FOREIGN KEY (district_id) REFERENCES police_districts (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE police_stations (
  id              BIGINT       NOT NULL AUTO_INCREMENT,
  sub_division_id BIGINT       NOT NULL,
  name            VARCHAR(150) NOT NULL,
  phone           VARCHAR(100),
  email           VARCHAR(200),
  address         VARCHAR(500),
  pin             VARCHAR(10),
  sort_order      INT          NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_police_stations_sub_division FOREIGN KEY (sub_division_id) REFERENCES police_sub_divisions (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE police_directory_settings (
  setting_key   VARCHAR(64) NOT NULL,
  setting_value TEXT,
  PRIMARY KEY (setting_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE drt_tribunals (
  id                BIGINT       NOT NULL AUTO_INCREMENT,
  kind              VARCHAR(20)  NOT NULL,
  name              VARCHAR(300) NOT NULL,
  location          VARCHAR(500),
  phone             VARCHAR(100),
  districts_label   VARCHAR(500),
  amount_label      VARCHAR(200),
  jurisdiction_text TEXT,
  note              TEXT,
  sort_order        INT          NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE drt_stations (
  id                BIGINT NOT NULL AUTO_INCREMENT,
  tribunal_id       BIGINT NOT NULL,
  police_station_id BIGINT NOT NULL,
  sort_order        INT    NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_drt_stations_tribunal FOREIGN KEY (tribunal_id)       REFERENCES drt_tribunals (id),
  CONSTRAINT fk_drt_stations_station  FOREIGN KEY (police_station_id) REFERENCES police_stations (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE consumer_commissions (
  id         BIGINT       NOT NULL AUTO_INCREMENT,
  kind       VARCHAR(20)  NOT NULL,
  name       VARCHAR(300) NOT NULL,
  location   VARCHAR(500),
  sort_order INT          NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE consumer_stations (
  id                BIGINT NOT NULL AUTO_INCREMENT,
  commission_id     BIGINT NOT NULL,
  police_station_id BIGINT NOT NULL,
  sort_order        INT    NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_consumer_stations_commission FOREIGN KEY (commission_id)     REFERENCES consumer_commissions (id),
  CONSTRAINT fk_consumer_stations_station    FOREIGN KEY (police_station_id) REFERENCES police_stations (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- cases and everything that hangs off a case ----------
CREATE TABLE cases (
  id                    BIGINT         NOT NULL AUTO_INCREMENT,
  title                 VARCHAR(500)   NOT NULL,
  case_no               VARCHAR(255)   NOT NULL,
  file_no               VARCHAR(255),
  file_seq              INT,
  deleted               BIT(1),
  deleted_at            DATETIME(6),
  cnr_no                VARCHAR(255),
  filing_date           DATE,
  client_side           VARCHAR(20),
  opposing_party        VARCHAR(255),
  opposing_father_name  VARCHAR(255),
  opposing_address      VARCHAR(500),
  opposing_phone        VARCHAR(30),
  court_id              BIGINT         NOT NULL,
  court_no              VARCHAR(255),
  case_nature           VARCHAR(255),
  relief_sought         VARCHAR(255),
  case_type             VARCHAR(255),
  fir_no                VARCHAR(255),
  fir_section           VARCHAR(255),
  police_station        VARCHAR(255),
  police_station_id     BIGINT,
  cheque_no             VARCHAR(50),
  cheque_date           DATE,
  memo_date             DATE,
  bouncing_reason       VARCHAR(255),
  claim_amount          DECIMAL(14,2),
  notice_date           DATE,
  status                VARCHAR(255),
  description           VARCHAR(255),
  next_hearing          DATE,
  listing_no            INT,
  listing_date          DATE,
  fee_type              VARCHAR(255),
  total_fee_amount      DECIMAL(12,2),
  total_fee_amount_date DATE,
  total_fee_paid        BIT(1)         NOT NULL,
  initial_amount        DECIMAL(12,2),
  initial_amount_date   DATE,
  initial_paid          BIT(1)         NOT NULL,
  date_wise_amount      DECIMAL(12,2),
  client_id             BIGINT         NOT NULL,
  user_id               BIGINT         NOT NULL,
  whatsapp_reminders    BIT(1),
  reminder_days_before  INT,
  created_at            DATETIME(6),
  updated_at            DATETIME(6),
  PRIMARY KEY (id),
  CONSTRAINT uk_cases_case_no UNIQUE (case_no),
  KEY idx_cases_next_hearing (next_hearing),
  KEY idx_cases_cnr_no (cnr_no),
  KEY idx_cases_user_status (user_id, status),
  -- a court row cannot be removed while a case (even a deleted one) is linked to it
  CONSTRAINT fk_cases_court   FOREIGN KEY (court_id)  REFERENCES courts (id),
  CONSTRAINT fk_cases_client  FOREIGN KEY (client_id) REFERENCES clients (id),
  CONSTRAINT fk_cases_user    FOREIGN KEY (user_id)   REFERENCES users (id),
  -- the station of a police challan case (set when the name matches exactly one station)
  CONSTRAINT fk_cases_police_station FOREIGN KEY (police_station_id) REFERENCES police_stations (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- other clients in the same case (ordered list)
CREATE TABLE case_additional_clients (
  case_id   BIGINT NOT NULL,
  client_id BIGINT NOT NULL,
  `position` INT   NOT NULL,
  PRIMARY KEY (case_id, `position`),
  CONSTRAINT fk_case_extra_clients_case   FOREIGN KEY (case_id)   REFERENCES cases (id),
  CONSTRAINT fk_case_extra_clients_client FOREIGN KEY (client_id) REFERENCES clients (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- role of each client in a case: client id -> sub type
CREATE TABLE case_client_sub_types (
  case_id   BIGINT NOT NULL,
  client_id BIGINT NOT NULL,
  sub_type  VARCHAR(40),
  PRIMARY KEY (case_id, client_id),
  CONSTRAINT fk_case_sub_types_case FOREIGN KEY (case_id) REFERENCES cases (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE case_hearing_fees (
  id              BIGINT        NOT NULL AUTO_INCREMENT,
  `date`          DATE,
  amount          DECIMAL(12,2),
  amount_received DECIMAL(12,2),
  paid            BIT(1)        NOT NULL,
  paid_at         DATETIME(6),
  case_id         BIGINT        NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_hearing_fees_case FOREIGN KEY (case_id) REFERENCES cases (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE case_stage_fees (
  id      BIGINT        NOT NULL AUTO_INCREMENT,
  name    VARCHAR(255),
  amount  DECIMAL(12,2),
  paid    BIT(1)        NOT NULL,
  paid_at DATETIME(6),
  case_id BIGINT        NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_stage_fees_case FOREIGN KEY (case_id) REFERENCES cases (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE hearings (
  id                  BIGINT       NOT NULL AUTO_INCREMENT,
  `date`              DATE         NOT NULL,
  `time`              VARCHAR(255),
  notes               TEXT,
  outcome             VARCHAR(255),
  order_doc_id        VARCHAR(255),
  order_doc_name      VARCHAR(255),
  order_seq           INT,
  no_order_on_record  BIT(1),
  ecourts_order_file  VARCHAR(255),
  judge_name          VARCHAR(255),
  case_id             BIGINT       NOT NULL,
  user_id             BIGINT       NOT NULL,
  created_at          DATETIME(6),
  updated_at          DATETIME(6),
  PRIMARY KEY (id),
  KEY idx_hearings_case_date (case_id, `date`),
  KEY idx_hearings_user_date (user_id, `date`),
  CONSTRAINT fk_hearings_case FOREIGN KEY (case_id) REFERENCES cases (id),
  CONSTRAINT fk_hearings_user FOREIGN KEY (user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE tasks (
  id           BIGINT       NOT NULL AUTO_INCREMENT,
  title        VARCHAR(255) NOT NULL,
  description  VARCHAR(255),
  status       VARCHAR(255),
  category     VARCHAR(255),
  due_date     DATE,
  user_id      BIGINT       NOT NULL,
  created_at   DATETIME(6),
  updated_at   DATETIME(6),
  completed_at DATETIME(6),
  PRIMARY KEY (id),
  KEY idx_tasks_user_status (user_id, status),
  KEY idx_tasks_due_date (due_date),
  CONSTRAINT fk_tasks_user FOREIGN KEY (user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE office_expenses (
  id              BIGINT        NOT NULL AUTO_INCREMENT,
  user_id         BIGINT        NOT NULL,
  submitted_by_id BIGINT        NOT NULL,
  description     VARCHAR(255)  NOT NULL,
  amount          DECIMAL(12,2) NOT NULL,
  upi_id          VARCHAR(255),
  qr_code_id      VARCHAR(255),
  paid            BIT(1)        NOT NULL,
  paid_at         DATETIME(6),
  created_at      DATETIME(6)   NOT NULL,
  updated_at      DATETIME(6),
  PRIMARY KEY (id),
  CONSTRAINT fk_office_expenses_user         FOREIGN KEY (user_id)         REFERENCES users (id),
  CONSTRAINT fk_office_expenses_submitted_by FOREIGN KEY (submitted_by_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE no_hearing_dates (
  id           BIGINT NOT NULL AUTO_INCREMENT,
  user_id      BIGINT NOT NULL,
  blocked_date DATE   NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT uk_no_hearing_user_date UNIQUE (user_id, blocked_date),
  CONSTRAINT fk_no_hearing_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- documents and QR images (the files themselves live in file storage, only the key is kept here) ----------
CREATE TABLE documents (
  id          VARCHAR(36)  NOT NULL,
  name        VARCHAR(512) NOT NULL,
  type        VARCHAR(255),
  file_name   VARCHAR(512),
  mime_type   VARCHAR(255),
  size_bytes  BIGINT       NOT NULL,
  storage_key VARCHAR(255) NOT NULL,
  case_id     BIGINT,
  client_id   BIGINT,
  order_seq   INT,
  order_date  DATE,
  user_id     BIGINT,
  uploaded_at DATETIME(6),
  PRIMARY KEY (id),
  KEY idx_documents_user (user_id),
  KEY idx_documents_case (case_id),
  KEY idx_documents_client (client_id),
  -- rows go with their owner (the services remove the files)
  CONSTRAINT fk_documents_case   FOREIGN KEY (case_id)   REFERENCES cases (id)   ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_documents_client FOREIGN KEY (client_id) REFERENCES clients (id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_documents_user   FOREIGN KEY (user_id)   REFERENCES users (id)   ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE qr_codes (
  id         VARCHAR(36) NOT NULL,
  user_id    BIGINT,
  image      LONGTEXT,
  created_at DATETIME(6),
  PRIMARY KEY (id),
  KEY idx_qr_codes_user (user_id),
  CONSTRAINT fk_qr_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- contact form ----------
CREATE TABLE contact_messages (
  id          BIGINT       NOT NULL AUTO_INCREMENT,
  account_id  BIGINT,
  role        VARCHAR(255),
  name        VARCHAR(255) NOT NULL,
  email       VARCHAR(255) NOT NULL,
  phone       VARCHAR(255),
  category    VARCHAR(255) NOT NULL,
  subject     VARCHAR(200) NOT NULL,
  message     TEXT         NOT NULL,
  status      VARCHAR(255) NOT NULL,
  user_unread BIT(1),
  created_at  DATETIME(6)  NOT NULL,
  updated_at  DATETIME(6),
  PRIMARY KEY (id),
  -- support history survives a deleted account
  CONSTRAINT fk_message_account FOREIGN KEY (account_id) REFERENCES users (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE contact_replies (
  id         BIGINT       NOT NULL AUTO_INCREMENT,
  message_id BIGINT       NOT NULL,
  admin_name VARCHAR(255) NOT NULL,
  body       TEXT         NOT NULL,
  channel    VARCHAR(10),
  emailed    BIT(1),
  created_at DATETIME(6)  NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_reply_message FOREIGN KEY (message_id) REFERENCES contact_messages (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- notifications ----------
CREATE TABLE notifications (
  id          BIGINT       NOT NULL AUTO_INCREMENT,
  source      VARCHAR(255) NOT NULL,
  title       VARCHAR(255) NOT NULL,
  message     LONGTEXT,
  `date`      DATE         NOT NULL,
  file_name   VARCHAR(255),
  mime_type   VARCHAR(255),
  size_bytes  BIGINT       NOT NULL,
  storage_key VARCHAR(255),
  important   BIT(1),
  created_at  DATETIME(6),
  updated_at  DATETIME(6),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE notification_dismissals (
  id              BIGINT      NOT NULL AUTO_INCREMENT,
  user_id         BIGINT      NOT NULL,
  notification_id BIGINT      NOT NULL,
  dismissed_at    DATETIME(6),
  PRIMARY KEY (id),
  CONSTRAINT uk_notif_dismissal_user_notif UNIQUE (user_id, notification_id),
  CONSTRAINT fk_dismissal_user   FOREIGN KEY (user_id)         REFERENCES users (id)         ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_dismissal_notice FOREIGN KEY (notification_id) REFERENCES notifications (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- one-time codes ----------
CREATE TABLE registration_otps (
  id           BIGINT       NOT NULL AUTO_INCREMENT,
  email        VARCHAR(255) NOT NULL,
  code_hash    VARCHAR(255) NOT NULL,
  expires_at   DATETIME(6)  NOT NULL,
  verified     BIT(1)       NOT NULL,
  attempts     INT          NOT NULL,
  last_sent_at DATETIME(6)  NOT NULL,
  created_at   DATETIME(6),
  PRIMARY KEY (id),
  CONSTRAINT uk_registration_otps_email UNIQUE (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE password_reset_otps (
  id           BIGINT       NOT NULL AUTO_INCREMENT,
  email        VARCHAR(255) NOT NULL,
  role         VARCHAR(255) NOT NULL,
  code_hash    VARCHAR(255) NOT NULL,
  expires_at   DATETIME(6)  NOT NULL,
  attempts     INT          NOT NULL,
  last_sent_at DATETIME(6)  NOT NULL,
  created_at   DATETIME(6),
  PRIMARY KEY (id),
  CONSTRAINT uk_password_reset_otps_email_role UNIQUE (email, role)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE email_change_otps (
  id           BIGINT       NOT NULL AUTO_INCREMENT,
  account_id   BIGINT       NOT NULL,
  new_email    VARCHAR(255) NOT NULL,
  code_hash    VARCHAR(255) NOT NULL,
  expires_at   DATETIME(6)  NOT NULL,
  attempts     INT          NOT NULL,
  last_sent_at DATETIME(6)  NOT NULL,
  created_at   DATETIME(6),
  PRIMARY KEY (id),
  CONSTRAINT uk_email_change_otps_account UNIQUE (account_id),
  -- a pending code goes with the account
  CONSTRAINT fk_email_otp_account FOREIGN KEY (account_id) REFERENCES users (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- WhatsApp log ----------
CREATE TABLE whatsapp_message_log (
  id           BIGINT       NOT NULL AUTO_INCREMENT,
  user_id      BIGINT,
  case_id      BIGINT,
  client_id    BIGINT,
  phone        VARCHAR(255),
  kind         ENUM('HEARING_REMINDER','PAYMENT_DUE'),
  origin       ENUM('AUTO','MANUAL'),
  status       ENUM('SENT','DRY_RUN','FAILED'),
  hearing_date DATE,
  error        VARCHAR(500),
  created_at   DATETIME(6),
  PRIMARY KEY (id),
  CONSTRAINT fk_wa_log_user   FOREIGN KEY (user_id)   REFERENCES users (id)   ON DELETE CASCADE  ON UPDATE CASCADE,
  -- the log survives a hard-deleted case or client
  CONSTRAINT fk_wa_log_case   FOREIGN KEY (case_id)   REFERENCES cases (id)   ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT fk_wa_log_client FOREIGN KEY (client_id) REFERENCES clients (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- sign-in log (Admin > Login Activity) ----------
-- Failed attempts on an unknown email have no user_id. Rows of a deleted account go with it, the rest is deleted after
-- loginlog.retention-days by the nightly cleanup.
CREATE TABLE login_log (
  id             BIGINT       NOT NULL AUTO_INCREMENT,
  user_id        BIGINT       NULL,
  email          VARCHAR(255),
  role           VARCHAR(20),
  event_type     ENUM('LOGIN','LOGIN_FAILED','LOGOUT') NOT NULL,
  method         ENUM('PASSWORD','GOOGLE'),
  failure_reason VARCHAR(255),
  ip_address     VARCHAR(64),
  user_agent     VARCHAR(255),
  created_at     DATETIME(6)  NOT NULL,
  PRIMARY KEY (id),
  KEY idx_login_log_created (created_at),
  KEY idx_login_log_user    (user_id, created_at),
  CONSTRAINT fk_login_log_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- calendar, holidays, PDFs, forms, fee calculator ----------
CREATE TABLE holidays (
  id          BIGINT       NOT NULL AUTO_INCREMENT,
  `date`      DATE         NOT NULL,
  label       VARCHAR(255) NOT NULL,
  description VARCHAR(255),
  court_type  VARCHAR(255),
  created_at  DATETIME(6),
  updated_at  DATETIME(6),
  PRIMARY KEY (id),
  CONSTRAINT uk_holidays_date UNIQUE (`date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE court_calendars (
  id          BIGINT       NOT NULL AUTO_INCREMENT,
  `year`      INT          NOT NULL,
  file_name   VARCHAR(255) NOT NULL,
  storage_key VARCHAR(255) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT uk_court_calendars_year UNIQUE (`year`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE district_pdfs (
  id               BIGINT       NOT NULL AUTO_INCREMENT,
  section          ENUM('JUDGES_LIST','BAIL_ROSTER','DUTY_MAGISTRATE') NOT NULL,
  court            VARCHAR(255) NOT NULL,
  district         VARCHAR(255) NOT NULL,
  pdf_file_name    VARCHAR(255),
  pdf_size_bytes   BIGINT,
  pdf_storage_key  VARCHAR(255),
  created_at       DATETIME(6),
  updated_at       DATETIME(6),
  PRIMARY KEY (id),
  CONSTRAINT uk_district_pdfs_section_district UNIQUE (section, district)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE legal_forms (
  id          BIGINT       NOT NULL AUTO_INCREMENT,
  name        VARCHAR(255) NOT NULL,
  description LONGTEXT,
  field_config LONGTEXT,
  fillable    BIT(1),
  field_count INT,
  sort_order  INT,
  file_name   VARCHAR(255),
  mime_type   VARCHAR(255),
  size_bytes  BIGINT       NOT NULL,
  storage_key VARCHAR(255) NOT NULL,
  uploaded_at DATETIME(6),
  updated_at  DATETIME(6),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- one JSON row (id 1); the backend saves the built-in rules itself when this table is empty
CREATE TABLE fee_calculator_config (
  id         BIGINT   NOT NULL,
  config     LONGTEXT NOT NULL,
  updated_at DATETIME(6),
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
